/**
 * FormDraftService
 *
 * フォームの途中入力状態 (下書き) を localStorage に保存し、
 * 再訪時に自動復元するための汎用サービス。
 *
 * 使い方:
 *   ngOnInit で `const draft = draftSvc.load<MyForm>('appeal-create:' + id);` で
 *   データを復元し、フィールドに代入。
 *   入力変化時に `draftSvc.save(key, obj)` で自動 debounce 保存。
 *   送信完了 / キャンセル時に `draftSvc.clear(key)`。
 *   ngOnDestroy で `draftSvc.flush()` で pending な保存を即時反映。
 *
 * ユーザー指示 (2026-04-21):
 *   コミュニティ各種作成フォーム / チャット入力で「他ページ遷移 → 戻り →
 *   入力エリアクリック」で下書きが再現されるようにする。
 */
import { Injectable } from '@angular/core';

const STORAGE_PREFIX = 'schecon.draft.v1:';
const DEBOUNCE_MS = 300;

@Injectable({ providedIn: 'root' })
export class FormDraftService {
  private timers = new Map<string, any>();

  /** 保存済み下書きを取得。無ければ null */
  load<T = any>(key: string): T | null {
    if (typeof localStorage === 'undefined') return null;
    try {
      const raw = localStorage.getItem(STORAGE_PREFIX + key);
      if (!raw) return null;
      return JSON.parse(raw) as T;
    } catch { return null; }
  }

  /** debounce つき保存 (頻繁な呼び出しを抑制) */
  save(key: string, data: unknown): void {
    if (typeof localStorage === 'undefined') return;
    // 空なら clear と等価
    if (data == null || (typeof data === 'object' && Object.keys(data as object).length === 0)) {
      this.clear(key);
      return;
    }
    if (this.timers.has(key)) clearTimeout(this.timers.get(key));
    this.timers.set(key, setTimeout(() => this.flush(key, data), DEBOUNCE_MS));
  }

  /** debounce を待たずに即時保存。遷移直前などに使う */
  flush(key: string, data: unknown): void {
    if (typeof localStorage === 'undefined') return;
    this.timers.delete(key);
    try {
      localStorage.setItem(STORAGE_PREFIX + key, JSON.stringify(data));
    } catch { /* quota exceeded 等は無視 */ }
  }

  /** 下書きを削除 */
  clear(key: string): void {
    if (typeof localStorage === 'undefined') return;
    try {
      localStorage.removeItem(STORAGE_PREFIX + key);
    } catch {}
    if (this.timers.has(key)) {
      clearTimeout(this.timers.get(key));
      this.timers.delete(key);
    }
  }

  /** 全件クリア (ログアウト時などに利用) */
  clearAll(): void {
    if (typeof localStorage === 'undefined') return;
    try {
      const keys: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(STORAGE_PREFIX)) keys.push(k);
      }
      keys.forEach(k => localStorage.removeItem(k));
    } catch {}
    this.timers.forEach(t => clearTimeout(t));
    this.timers.clear();
  }
}
