import { Component, Inject, Input, ChangeDetectionStrategy, OnInit, OnDestroy, HostListener, ChangeDetectorRef, Optional } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { CommunityService } from '../../services/community.service';
import { CommunityEvent } from '../../models/community.model';
import { FormDraftService } from '../../../../shared/services/form-draft.service';
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';

export interface EventCreateData {
  communityId: string;
  /** 編集モード用 (ユーザー指示 2026-04-21) */
  editing?: CommunityEvent;
}

interface EventDraft {
  title: string; description: string; date: string; endDate: string;
  location: string; isOnline: boolean; meetingUrl: string;
  maxParticipants: number | null; tagsInput: string; imageUrl: string;
}

@Component({
  selector: 'app-event-create',
  standalone: true,
  imports: [CommonModule, FormsModule, MatDialogModule],
  templateUrl: './event-create.component.html',
  styleUrls: ['./event-create.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventCreateComponent implements OnInit, OnDestroy {
  title = '';
  description = '';
  date = '';
  endDate = '';
  location = '';
  isOnline = false;
  meetingUrl = '';
  maxParticipants: number | null = null;
  tagsInput = '';
  imageUrl = '';

  /** fix (2026-04-27): ページ版でも利用可能にするための fallback Input */
  @Input() communityIdInput?: string;
  @Input() editingInput?: CommunityEvent;

  /** モーダル時は data、ページ時は Input を使う */
  private get communityId(): string {
    return this.data?.communityId || this.communityIdInput || '';
  }
  private get editing(): CommunityEvent | undefined {
    return this.data?.editing || this.editingInput;
  }

  private get draftKey(): string { return 'event-create:' + this.communityId; }
  private snapshot(): EventDraft {
    return {
      title: this.title, description: this.description,
      date: this.date, endDate: this.endDate,
      location: this.location, isOnline: this.isOnline, meetingUrl: this.meetingUrl,
      maxParticipants: this.maxParticipants, tagsInput: this.tagsInput, imageUrl: this.imageUrl,
    };
  }

  /* STEP 9: KeyboardManager 適用 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;

  constructor(
    /* fix (2026-04-27): モーダル/ページ両対応のため Optional に */
    @Optional() private dialogRef: MatDialogRef<EventCreateComponent>,
    @Optional() @Inject(MAT_DIALOG_DATA) private data: EventCreateData,
    @Optional() private location_: Location,
    @Optional() private router: Router,
    private communityService: CommunityService,
    private draftSvc: FormDraftService,
    private keyboard: KeyboardManagerService,
    private cdr: ChangeDetectorRef,
  ) {
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  get isEdit(): boolean { return !!this.editing; }

  ngOnInit(): void {
    // 編集モード (ユーザー指示 2026-04-21)
    if (this.editing) {
      const e = this.editing;
      this.title = e.title;
      this.description = e.description;
      this.date = e.date ? new Date(e.date).toISOString().slice(0, 16) : '';
      this.endDate = e.endDate ? new Date(e.endDate).toISOString().slice(0, 16) : '';
      this.location = e.location;
      this.isOnline = !!e.isOnline;
      this.meetingUrl = e.meetingUrl || '';
      this.maxParticipants = e.maxParticipants ?? null;
      this.tagsInput = (e.tags || []).join(', ');
      this.imageUrl = e.imageUrl || '';
      return;
    }
    const d = this.draftSvc.load<EventDraft>(this.draftKey);
    if (d) {
      this.title = d.title || '';
      this.description = d.description || '';
      this.date = d.date || '';
      this.endDate = d.endDate || '';
      this.location = d.location || '';
      this.isOnline = !!d.isOnline;
      this.meetingUrl = d.meetingUrl || '';
      this.maxParticipants = d.maxParticipants ?? null;
      this.tagsInput = d.tagsInput || '';
      this.imageUrl = d.imageUrl || '';
    }
  }

  onFieldChange(): void {
    if (this.isEdit) return;
    this.draftSvc.save(this.draftKey, this.snapshot());
  }

  @HostListener('window:beforeunload')
  onBeforeUnload(): void {
    if (this.isEdit) return;
    this.draftSvc.flush(this.draftKey, this.snapshot());
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
    if (this.isEdit) return;
    const s = this.snapshot();
    if (s.title || s.description || s.date || s.location || s.tagsInput) {
      this.draftSvc.flush(this.draftKey, s);
    }
  }

  /** fix (2026-04-27 v2): モーダル時は dialogRef.close、ページ時は:
   *  - 成功 (result あり): /community/:id へ navigate して community-detail を再マウント
   *    → 内部の active list (募集/イベント/スレッド/アピール) が ngOnInit で loadXxx 再実行
   *  - キャンセル/失敗 (result なし): location.back で履歴を消費
   */
  private closeOrBack(result?: any): void {
    if (this.dialogRef) {
      this.dialogRef.close(result);
      return;
    }
    if (result && this.router && this.communityId) {
      /* 成功: 強制再マウントで一覧を更新 */
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => {
        this.router!.navigate(['/community', this.communityId]);
      });
      return;
    }
    if (this.location_ && window.history.length > 1) {
      this.location_.back();
    } else if (this.router && this.communityId) {
      this.router.navigate(['/community', this.communityId]);
    }
  }

  onCancel(): void {
    this.closeOrBack();
  }

  onCreate(): void {
    if (!this.title.trim()) return;

    const tags = this.tagsInput
      .split(',')
      .map(t => t.trim())
      .filter(t => t.length > 0);

    const payload = {
      communityId: this.communityId,
      title: this.title.trim(),
      description: this.description.trim(),
      imageUrl: this.imageUrl.trim() || undefined,
      date: this.date ? new Date(this.date) : new Date(),
      endDate: this.endDate ? new Date(this.endDate) : undefined,
      location: this.location.trim(),
      isOnline: this.isOnline,
      meetingUrl: this.isOnline ? this.meetingUrl.trim() : undefined,
      maxParticipants: this.maxParticipants || undefined,
      tags: tags.length > 0 ? tags : undefined,
    };

    if (this.isEdit && this.editing) {
      this.communityService
        .updateEvent(this.editing.id, payload)
        .subscribe(updated => this.closeOrBack(updated));
      return;
    }

    this.communityService.createEvent(payload).subscribe(event => {
      this.draftSvc.clear(this.draftKey);
      this.closeOrBack(event);
    });
  }
}
/* fix (2026-04-27): @Optional MatDialogRef 化、ページ版でも再利用可能 */
