import { Component, Inject, Input, ChangeDetectionStrategy, OnInit, OnDestroy, HostListener, ChangeDetectorRef, Optional } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogRef, MAT_DIALOG_DATA, MatDialogModule } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';
import { Router } from '@angular/router';
import { ImageUploadComponent } from '../../../../shared/components/image-upload/image-upload.component';
import { FormDraftService } from '../../../../shared/services/form-draft.service';
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';
import { ThreadPost } from '../../models/community.model';
/* fix D7 (2026-04-28): 真の症状は createThread() が一度も呼ばれていなかった事。
   thread-create コンポーネントから直接 CommunityService.createThread を呼び、
   threadsSubject.next で list が auto-refresh されるようにする。 */
import { CommunityService } from '../../services/community.service';
import { NotificationService } from '../../../../shared/services/notification.service';

interface ThreadDraft { title: string; content: string; }

export interface ThreadCreateData {
  communityId: string;
  /** 編集モード用 (ユーザー指示 2026-04-21) */
  editing?: ThreadPost;
}

@Component({
  selector: 'app-thread-create',
  standalone: true,
  imports: [CommonModule, FormsModule, MatDialogModule, MatIconModule, ImageUploadComponent],
  templateUrl: './thread-create.component.html',
  styleUrls: ['./thread-create.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ThreadCreateComponent implements OnInit, OnDestroy {
  title = '';
  content = '';
  imageFile: File | null = null;

  /** fix (2026-04-27): ページ版でも利用可能にするための fallback Input */
  @Input() communityIdInput?: string;
  @Input() editingInput?: ThreadPost;

  /** モーダル時は data、ページ時は Input を使う */
  private get communityId(): string {
    return this.data?.communityId || this.communityIdInput || '';
  }
  private get editing(): ThreadPost | undefined {
    return this.data?.editing || this.editingInput;
  }

  private get draftKey(): string { return 'thread-create:' + this.communityId; }
  private snapshot(): ThreadDraft { return { title: this.title, content: this.content }; }
  get isEdit(): boolean { return !!this.editing; }

  /* STEP 9: KeyboardManager で SP キーボード時の dialog 高さを補正 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;

  constructor(
    /* fix (2026-04-27): モーダル/ページ両対応のため Optional に */
    @Optional() private dialogRef: MatDialogRef<ThreadCreateComponent>,
    @Optional() @Inject(MAT_DIALOG_DATA) public data: ThreadCreateData,
    @Optional() private location: Location,
    @Optional() private router: Router,
    private draftSvc: FormDraftService,
    private keyboard: KeyboardManagerService,
    private cdr: ChangeDetectorRef,
    /* fix D7 (2026-04-28): スレッド作成サービスを注入。
       ページ版/モーダル版どちらからも、ここで直接 createThread を実行する。 */
    private communityService: CommunityService,
    private notification: NotificationService,
  ) {
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  ngOnInit(): void {
    if (this.editing) {
      this.title = this.editing.title;
      this.content = this.editing.content;
      return;
    }
    const d = this.draftSvc.load<ThreadDraft>(this.draftKey);
    if (d) {
      this.title = d.title || '';
      this.content = d.content || '';
    }
  }

  onFieldChange(): void {
    if (this.isEdit) return;
    this.draftSvc.save(this.draftKey, this.snapshot());
  }

  @HostListener('window:beforeunload')
  onBeforeUnload(): void {
    if (this.isEdit) return;
    this.draftSvc.flush(this.draftKey, this.snapshot());
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
    if (this.isEdit) return;
    const s = this.snapshot();
    if (s.title || s.content) this.draftSvc.flush(this.draftKey, s);
  }

  onImageSelected(event: { file: File; previewUrl: string }): void {
    this.imageFile = event.file;
  }

  onImageRemoved(): void {
    this.imageFile = null;
  }

  /** fix (2026-04-27 v2): モーダル時は dialogRef.close、ページ時は:
   *  - 成功 (result あり): /community/:id へ navigate して community-detail を再マウント
   *    → 内部の active list (募集/イベント/スレッド/アピール) が ngOnInit で loadXxx 再実行
   *  - キャンセル/失敗 (result なし): location.back で履歴を消費
   */
  private closeOrBack(result?: any): void {
    if (this.dialogRef) {
      this.dialogRef.close(result);
      return;
    }
    if (result && this.router && this.communityId) {
      /* 成功: 強制再マウントで一覧を更新 */
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => {
        this.router!.navigate(['/community', this.communityId]);
      });
      return;
    }
    if (this.location && window.history.length > 1) {
      this.location.back();
    } else if (this.router && this.communityId) {
      this.router.navigate(['/community', this.communityId]);
    }
  }

  onSubmit(): void {
    if (!(this.title.trim() && this.content.trim())) return;
    this.draftSvc.clear(this.draftKey);
    const payload = {
      title: this.title.trim(),
      content: this.content.trim(),
      editing: this.editing,
    };

    /* fix D7 (2026-04-28): 編集モードは呼び出し元 (thread-list の編集ハンドラ等)
       に委譲、新規モードはここで CommunityService.createThread を直接実行して
       threadsSubject に next させ、list を auto-refresh する。
       これまでは payload を closeOrBack に渡すだけで、ページ版では誰も
       createThread を呼んでいなかった (← 真因)。 */
    if (this.isEdit) {
      this.closeOrBack(payload);
      return;
    }

    this.communityService.createThread({
      communityId: this.communityId,
      title: payload.title,
      content: payload.content,
    }).subscribe({
      next: (created) => {
        this.notification.success('スレッドを投稿しました');
        this.closeOrBack({ ...payload, created });
      },
      error: () => {
        this.notification.warn('スレッドの投稿に失敗しました');
      },
    });
  }

  onCancel(): void {
    this.closeOrBack();
  }
}
/* fix (2026-04-27): @Optional MatDialogRef 化、ページ版でも再利用可能 */
