import { Component, Inject, Input, ChangeDetectionStrategy, OnInit, OnDestroy, HostListener, ChangeDetectorRef, Optional } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';
import { Router } from '@angular/router';
import { CommunityService } from '../../services/community.service';
import { Appeal } from '../../models/community.model';
import { ImageUploadComponent } from '../../../../shared/components/image-upload/image-upload.component';
import { FormDraftService } from '../../../../shared/services/form-draft.service';
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';

export interface AppealCreateData {
  communityId: string;
  /** 編集モード用: 既存のアピール (ユーザー指示 2026-04-21) */
  editing?: Appeal;
}

interface AppealDraft {
  title: string;
  selfIntro: string;
  skillsText: string;
  wantToMeet: string;
}

@Component({
  selector: 'app-appeal-create',
  standalone: true,
  imports: [CommonModule, FormsModule, MatDialogModule, MatIconModule, ImageUploadComponent],
  templateUrl: './appeal-create.component.html',
  styleUrls: ['./appeal-create.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppealCreateComponent implements OnInit, OnDestroy {
  title = '';
  selfIntro = '';
  skillsText = '';
  wantToMeet = '';
  imageFiles: File[] = [];
  imagePreviewUrls: string[] = [];

  /** fix (2026-04-27): ページ版でも利用可能にするための fallback Input */
  @Input() communityIdInput?: string;
  @Input() editingInput?: Appeal;

  /** モーダル時は data、ページ時は Input を使う */
  private get communityId(): string {
    return this.data?.communityId || this.communityIdInput || '';
  }
  private get editing(): Appeal | undefined {
    return this.data?.editing || this.editingInput;
  }

  private get draftKey(): string {
    return 'appeal-create:' + this.communityId;
  }

  /* STEP 9: KeyboardManager 適用 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;

  constructor(
    /* fix (2026-04-27): モーダル/ページ両対応のため Optional に */
    @Optional() private dialogRef: MatDialogRef<AppealCreateComponent>,
    @Optional() @Inject(MAT_DIALOG_DATA) private data: AppealCreateData,
    @Optional() private location: Location,
    @Optional() private router: Router,
    private communityService: CommunityService,
    private draftSvc: FormDraftService,
    private keyboard: KeyboardManagerService,
    private cdr: ChangeDetectorRef,
  ) {
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  get isEdit(): boolean { return !!this.editing; }

  ngOnInit(): void {
    // 編集モード: 既存データでプリフィル (ユーザー指示 2026-04-21)
    if (this.editing) {
      const a = this.editing;
      this.title = a.title;
      this.selfIntro = a.selfIntro;
      this.skillsText = (a.skills || []).join(', ');
      this.wantToMeet = a.wantToMeet;
      return;
    }
    // 前回の下書きを復元
    const d = this.draftSvc.load<AppealDraft>(this.draftKey);
    if (d) {
      this.title = d.title || '';
      this.selfIntro = d.selfIntro || '';
      this.skillsText = d.skillsText || '';
      this.wantToMeet = d.wantToMeet || '';
    }
  }

  /** ngModelChange から呼ぶ統合ハンドラ (各フィールド入力で draft 保存) */
  onFieldChange(): void {
    if (this.isEdit) return;
    this.draftSvc.save(this.draftKey, {
      title: this.title,
      selfIntro: this.selfIntro,
      skillsText: this.skillsText,
      wantToMeet: this.wantToMeet,
    } as AppealDraft);
  }

  @HostListener('window:beforeunload')
  onBeforeUnload(): void {
    this.draftSvc.flush(this.draftKey, {
      title: this.title,
      selfIntro: this.selfIntro,
      skillsText: this.skillsText,
      wantToMeet: this.wantToMeet,
    });
  }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
    if (this.isEdit) return;
    // モーダル閉鎖時もここで保存 (キャンセル/ESC 経由のとき)
    if (this.title || this.selfIntro || this.skillsText || this.wantToMeet) {
      this.draftSvc.flush(this.draftKey, {
        title: this.title,
        selfIntro: this.selfIntro,
        skillsText: this.skillsText,
        wantToMeet: this.wantToMeet,
      });
    }
  }

  onImageSelected(event: { file: File; previewUrl: string }): void {
    if (this.imageFiles.length < 5) {
      this.imageFiles.push(event.file);
      this.imagePreviewUrls.push(event.previewUrl);
    }
  }

  onImageRemoved(): void {
    this.imageFiles = [];
    this.imagePreviewUrls = [];
  }

  removeImage(index: number): void {
    this.imageFiles.splice(index, 1);
    this.imagePreviewUrls.splice(index, 1);
  }

  /** fix (2026-04-27 v2): モーダル時は dialogRef.close、ページ時は:
   *  - 成功 (result あり): /community/:id へ navigate して community-detail を再マウント
   *    → 内部の active list (募集/イベント/スレッド/アピール) が ngOnInit で loadXxx 再実行
   *  - キャンセル/失敗 (result なし): location.back で履歴を消費
   */
  private closeOrBack(result?: any): void {
    if (this.dialogRef) {
      this.dialogRef.close(result);
      return;
    }
    if (result && this.router && this.communityId) {
      /* 成功: 強制再マウントで一覧を更新 */
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => {
        this.router!.navigate(['/community', this.communityId]);
      });
      return;
    }
    if (this.location && window.history.length > 1) {
      this.location.back();
    } else if (this.router && this.communityId) {
      this.router.navigate(['/community', this.communityId]);
    }
  }

  onCancel(): void {
    this.closeOrBack();
  }

  onCreate(): void {
    if (!this.title.trim()) return;

    const skills = this.skillsText
      .split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0);

    const payload = {
      communityId: this.communityId,
      title: this.title.trim(),
      selfIntro: this.selfIntro.trim(),
      skills,
      wantToMeet: this.wantToMeet.trim(),
    };

    if (this.isEdit && this.editing) {
      this.communityService
        .updateAppeal(this.editing.id, payload)
        .subscribe(updated => this.closeOrBack(updated));
      return;
    }

    this.communityService.createAppeal(payload).subscribe(appeal => {
      // 送信成功 → 下書きクリア
      this.draftSvc.clear(this.draftKey);
      this.closeOrBack(appeal);
    });
  }
}
/* fix (2026-04-27): @Optional MatDialogRef 化、ページ版でも再利用可能 */
