import { Component, Inject, Input, ChangeDetectionStrategy, OnInit, OnDestroy, HostListener, ChangeDetectorRef, Optional } from '@angular/core';
import { CommonModule, Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatDialogModule, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { MatIconModule } from '@angular/material/icon';
import { Router } from '@angular/router';
import { CommunityService } from '../../services/community.service';
import { Recruitment } from '../../models/community.model';
import { ImageUploadComponent } from '../../../../shared/components/image-upload/image-upload.component';
import { FormDraftService } from '../../../../shared/services/form-draft.service';
import { KeyboardManagerService } from '../../../../shared/services/keyboard-manager.service';
import { Subscription } from 'rxjs';

export interface RecruitmentCreateData {
  communityId: string;
  /** 編集モード用: 既存の募集 (ユーザー指示 2026-04-21) */
  editing?: Recruitment;
}

interface RecruitmentDraft {
  title: string; problem: string; details: string;
  deadline: string; hasCompensation: boolean; compensationDetails: string;
}

@Component({
  selector: 'app-recruitment-create',
  standalone: true,
  imports: [CommonModule, FormsModule, MatDialogModule, MatIconModule, ImageUploadComponent],
  templateUrl: './recruitment-create.component.html',
  styleUrls: ['./recruitment-create.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecruitmentCreateComponent implements OnInit, OnDestroy {
  title = '';
  problem = '';
  details = '';
  deadline = '';
  hasCompensation = false;
  compensationDetails = '';
  imageFiles: File[] = [];
  imagePreviewUrls: string[] = [];

  /** fix (2026-04-27): ページ版でも利用可能にするための fallback Input */
  @Input() communityIdInput?: string;
  @Input() editingInput?: Recruitment;

  /** モーダル時は data.communityId、ページ時は communityIdInput を使う */
  private get communityId(): string {
    return this.data?.communityId || this.communityIdInput || '';
  }
  private get editing(): Recruitment | undefined {
    return this.data?.editing || this.editingInput;
  }

  private get draftKey(): string { return 'recruitment-create:' + this.communityId; }
  private snapshot(): RecruitmentDraft {
    return {
      title: this.title, problem: this.problem, details: this.details,
      deadline: this.deadline, hasCompensation: this.hasCompensation,
      compensationDetails: this.compensationDetails,
    };
  }

  /* STEP 9: KeyboardManager 適用 */
  keyboardHeight = 0;
  private keyboardSub?: Subscription;

  constructor(
    /* fix (2026-04-27): モーダル/ページ両対応のため Optional に */
    @Optional() private dialogRef: MatDialogRef<RecruitmentCreateComponent>,
    @Optional() @Inject(MAT_DIALOG_DATA) private data: RecruitmentCreateData,
    @Optional() private location: Location,
    @Optional() private router: Router,
    private communityService: CommunityService,
    private draftSvc: FormDraftService,
    private keyboard: KeyboardManagerService,
    private cdr: ChangeDetectorRef,
  ) {
    this.keyboardSub = this.keyboard.keyboardHeight$.subscribe(h => {
      this.keyboardHeight = h;
      this.cdr.markForCheck();
    });
  }

  /** 編集モードか */
  get isEdit(): boolean { return !!this.editing; }

  ngOnInit(): void {
    // 編集モード: 既存データをプリフィル (ユーザー指示 2026-04-21)
    if (this.editing) {
      const r = this.editing;
      this.title = r.title;
      this.problem = r.problem;
      this.details = r.details;
      this.deadline = r.deadline ? new Date(r.deadline).toISOString().slice(0, 10) : '';
      this.hasCompensation = r.hasCompensation;
      this.compensationDetails = r.compensationDetails || '';
      return;
    }
    const d = this.draftSvc.load<RecruitmentDraft>(this.draftKey);
    if (d) {
      this.title = d.title || '';
      this.problem = d.problem || '';
      this.details = d.details || '';
      this.deadline = d.deadline || '';
      this.hasCompensation = !!d.hasCompensation;
      this.compensationDetails = d.compensationDetails || '';
    }
  }

  onFieldChange(): void {
    if (this.isEdit) return; // 編集中は下書きに汚さない
    this.draftSvc.save(this.draftKey, this.snapshot());
  }

  @HostListener('window:beforeunload')
  onBeforeUnload(): void { this.draftSvc.flush(this.draftKey, this.snapshot()); }

  ngOnDestroy(): void {
    this.keyboardSub?.unsubscribe();
    if (this.isEdit) return;
    const s = this.snapshot();
    if (s.title || s.problem || s.details || s.deadline || s.compensationDetails) {
      this.draftSvc.flush(this.draftKey, s);
    }
  }

  onImageSelected(event: { file: File; previewUrl: string }): void {
    if (this.imageFiles.length < 5) {
      this.imageFiles.push(event.file);
      this.imagePreviewUrls.push(event.previewUrl);
    }
  }

  onImageRemoved(): void {
    this.imageFiles = [];
    this.imagePreviewUrls = [];
  }

  removeImage(index: number): void {
    this.imageFiles.splice(index, 1);
    this.imagePreviewUrls.splice(index, 1);
  }

  /** fix (2026-04-27 v2): モーダル時は dialogRef.close、ページ時は:
   *  - 成功 (result あり): /community/:id へ navigate して community-detail を再マウント
   *    → 内部の active list (募集/イベント/スレッド/アピール) が ngOnInit で loadXxx 再実行
   *  - キャンセル/失敗 (result なし): location.back で履歴を消費
   */
  private closeOrBack(result?: any): void {
    if (this.dialogRef) {
      this.dialogRef.close(result);
      return;
    }
    if (result && this.router && this.communityId) {
      /* 成功: 強制再マウントで一覧を更新 */
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => {
        this.router!.navigate(['/community', this.communityId]);
      });
      return;
    }
    if (this.location && window.history.length > 1) {
      this.location.back();
    } else if (this.router && this.communityId) {
      this.router.navigate(['/community', this.communityId]);
    }
  }

  onCancel(): void {
    this.closeOrBack();
  }

  onCreate(): void {
    if (!this.title.trim()) return;

    const payload = {
      communityId: this.communityId,
      title: this.title.trim(),
      problem: this.problem.trim(),
      details: this.details.trim(),
      deadline: this.deadline ? new Date(this.deadline) : undefined,
      hasCompensation: this.hasCompensation,
      compensationDetails: this.hasCompensation ? this.compensationDetails.trim() : undefined,
    };

    if (this.isEdit && this.editing) {
      this.communityService
        .updateRecruitment(this.editing.id, payload)
        .subscribe(updated => this.closeOrBack(updated));
      return;
    }

    this.communityService.createRecruitment(payload).subscribe(recruitment => {
      this.draftSvc.clear(this.draftKey);
      this.closeOrBack(recruitment);
    });
  }
}
